import { Form, type FormSubmitDetail } from '@absoluteui/components/form';
import { TextInput } from '@absoluteui/components/text-input';
import { Button } from '@absoluteui/components/button';

const el = document.createElement('form');
document.body.append(el);
const field = (): HTMLDivElement => {
  const host = document.createElement('div');
  el.append(host);
  return host;
};
TextInput.create(field(), { label: 'Email', name: 'email', type: 'email', required: true, autocomplete: 'email' });
TextInput.create(field(), { label: 'Password', name: 'password', type: 'password', autocomplete: 'new-password', required: true, minLength: 12 });
TextInput.create(field(), { label: 'Confirm password', name: 'confirm', type: 'password', autocomplete: 'new-password', required: true });
const submit = document.createElement('button');
submit.type = 'submit';
submit.textContent = 'Create account';
Button.enhance(submit, { variant: 'primary' });
el.append(submit);

Form.create(el, {
  rules: [{ fields: ['password', 'confirm'], validate: (values) => (values.password === values.confirm ? null : 'Passwords do not match.') }],
});
el.addEventListener('aui-submit', (event) => {
  const { values } = (event as CustomEvent<FormSubmitDetail>).detail;
  el.dataset.account = typeof values.email === 'string' ? values.email : '';
});

import { Form, type FormErrors, type FormSubmitDetail } from '@absoluteui/components/form';
import { TextInput } from '@absoluteui/components/text-input';
import { Button } from '@absoluteui/components/button';

const el = document.createElement('form');
document.body.append(el);
const host = document.createElement('div');
el.append(host);
TextInput.create(host, { label: 'Username', name: 'username', required: true, autocomplete: 'username' });
const submit = document.createElement('button');
submit.type = 'submit';
submit.textContent = 'Register';
Button.enhance(submit, { variant: 'primary' });
el.append(submit);

function isFormErrors(value: unknown): value is FormErrors {
  return typeof value === 'object' && value !== null && Object.values(value).every((m) => typeof m === 'string');
}

const post = (url: string, body: unknown, signal?: AbortSignal): Promise<Response> =>
  fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), ...(signal ? { signal } : {}) });

const form = Form.create(el, {
  asyncTimeoutMs: 5000,
  // Runs after constraints and cross-field rules pass. Rejecting or timing out reports reason 'async-failed'.
  validate: async (values, signal) => {
    const response = await post('/api/username-check', values, signal);
    if (!response.ok) throw new Error(`Username check failed: ${response.status}`);
    const body: unknown = await response.json();
    if (!isFormErrors(body)) throw new Error('Unexpected response');
    return body;
  },
});

// Form prevents double submission only while the async validator runs; guard the save yourself.
el.addEventListener('aui-submit', (event) => {
  const { values } = (event as CustomEvent<FormSubmitDetail>).detail;
  submit.disabled = true;
  post('/api/register', values)
    .then(async (response) => {
      if (response.status !== 422) return;
      const body: unknown = await response.json();
      if (isFormErrors(body)) form.setErrors(body);
    })
    .catch(() => {
      // A name that matches no field is listed in the summary without a link.
      form.setErrors({ _form: 'Your account could not be created. Try again.' });
    })
    .finally(() => {
      submit.disabled = false;
    });
});

import { Form } from '@absoluteui/components/form';
import { FormField } from '@absoluteui/components/form-field';
import { Button } from '@absoluteui/components/button';

const el = document.createElement('form');
el.method = 'post';
el.action = '/contact';
document.body.append(el);

const zip = document.createElement('input');
zip.name = 'zip';
zip.inputMode = 'numeric';
zip.pattern = '[0-9]{5}';
const zipHost = document.createElement('div');
el.append(zipHost);
FormField.create(zipHost, { label: 'ZIP code', control: zip, required: true, description: 'Five digits' });

// Plain named native elements are serialized and reset too, but not validated.
const source = document.createElement('input');
source.type = 'hidden';
source.name = 'source';
source.value = 'footer';
el.append(source);

const submit = document.createElement('button');
submit.type = 'submit';
submit.name = 'intent';
submit.value = 'send';
submit.textContent = 'Send';
Button.enhance(submit, { variant: 'primary' });
el.append(submit);

// After validation passes and aui-submit is not prevented, the form is submitted natively (submitter name/value included).
Form.create(el, { submitMode: 'native', focusOnInvalid: 'first-field' });

import { Form, type FormState } from '@absoluteui/components/form';
import { TextInput } from '@absoluteui/components/text-input';
import { Button } from '@absoluteui/components/button';

const el = document.createElement('form');
document.body.append(el);
const host = document.createElement('div');
el.append(host);
TextInput.create(host, { label: 'Display name', name: 'displayName', value: 'Ada' });
const status = document.createElement('p');
const reset = document.createElement('button');
reset.type = 'reset';
reset.textContent = 'Discard changes';
Button.enhance(reset);
el.append(status, reset);

const form = Form.create(el);
// Emitted only when dirty, touched, submitting, submitCount, or valid actually changes.
el.addEventListener('aui-state-change', (event) => {
  const state = (event as CustomEvent<FormState>).detail;
  status.textContent = state.dirty ? 'You have unsaved changes.' : '';
});
// The native reset button is intercepted and calls form.reset().
el.addEventListener('aui-reset', () => {
  status.textContent = '';
});
window.addEventListener('beforeunload', (event) => {
  if (form.state.dirty) event.preventDefault();
});

import { checkText, Form, messageFor, type FormValues } from '@absoluteui/components/form';
import { TextInput } from '@absoluteui/components/text-input';

const el = document.createElement('form');
document.body.append(el);
for (const [label, name] of [['Contact method', 'method'], ['Contact email', 'contactEmail']] as const) {
  const host = document.createElement('div');
  el.append(host);
  TextInput.create(host, { label, name });
}

// Email is required only when the contact method is "email"; messages stay localized.
const emailRule = (values: FormValues): string | null => {
  const email = typeof values.contactEmail === 'string' ? values.contactEmail : '';
  const outcome = checkText(email, { type: 'email', required: values.method === 'email' });
  return outcome.error === null ? null : messageFor(outcome, { locale: 'en-US' });
};
Form.create(el, { rules: [{ fields: ['method', 'contactEmail'], validate: emailRule, target: 'contactEmail' }] });

import { configureAbsoluteUI } from '@absoluteui/core';
import '@absoluteui/components/form';

configureAbsoluteUI({ components: { form: { focusOnInvalid: 'first-field', asyncTimeoutMs: 5000 } } });

import { emit } from '@absoluteui/core';
import { Form, registerFormControl, type ControlValidity, type FormControl } from '@absoluteui/components/form';
import { Button } from '@absoluteui/components/button';

type Priority = 'low' | 'normal' | 'high';

/** A required toggle-button group. It implements the FormControl contract so Form can validate, serialize, reset, and focus it. */
class PriorityPicker implements FormControl {
  readonly name = 'priority';
  readonly label = 'Priority';
  readonly disabled = false;
  touched = false;
  #value: Priority | null = null;
  #customError: string | null = null;
  #showErrors = false;
  readonly #buttons: HTMLButtonElement[];
  readonly #message: HTMLParagraphElement;
  readonly #unregister: () => void;

  constructor(readonly host: HTMLElement) {
    const doc = host.ownerDocument;
    const legend = doc.createElement('p');
    legend.id = 'priority-label';
    legend.textContent = this.label;
    this.#message = doc.createElement('p');
    this.#message.id = 'priority-message';
    this.#buttons = (['low', 'normal', 'high'] as const).map((value) => {
      const button = doc.createElement('button');
      button.type = 'button';
      button.textContent = value;
      button.setAttribute('aria-pressed', 'false');
      button.setAttribute('aria-describedby', this.#message.id);
      button.addEventListener('click', () => {
        this.#value = value;
        this.#customError = null;
        this.#render();
        emit(host, 'aui-change', { value });
      });
      Button.enhance(button, { size: 'sm' });
      return button;
    });
    host.setAttribute('role', 'group');
    host.setAttribute('aria-labelledby', legend.id);
    host.replaceChildren(legend, ...this.#buttons, this.#message);
    host.addEventListener('focusout', () => {
      this.touched = true;
    });
    this.#render();
    // Registration makes the host discoverable by any Form that contains it.
    this.#unregister = registerFormControl(this);
  }

  get validity(): ControlValidity {
    if (this.#value === null) return { valid: false, message: 'Select a priority.' };
    if (this.#customError !== null) return { valid: false, message: this.#customError };
    return { valid: true, message: '' };
  }

  get dirty(): boolean {
    return this.#value !== null;
  }

  getFormValue(): Priority | null {
    return this.#value;
  }

  reportValidity(): boolean {
    this.#showErrors = true;
    this.#render();
    return this.validity.valid;
  }

  setCustomError(message: string | null): void {
    this.#customError = message === '' ? null : message;
    this.#render();
  }

  focus(): void {
    this.#buttons[0]?.focus();
  }

  reset(): void {
    this.#value = null;
    this.#customError = null;
    this.#showErrors = false;
    this.touched = false;
    this.#render();
  }

  destroy(): void {
    this.#unregister();
    this.host.replaceChildren();
  }

  #render(): void {
    for (const button of this.#buttons) button.setAttribute('aria-pressed', String(button.textContent === this.#value));
    this.#message.textContent = this.#showErrors ? this.validity.message : '';
  }
}

